shader_body {
    float2 n = 0;
    float2 N = 0;
    float2 q;
    float a = 0;
    float S = 1;
    float j = 0;
    float R;

    while (j < 100.0) {
        float k = 5.0 * j;
        float2x2 rot = { cos(k), -sin(k), sin(k), cos(k) };
        n = mul(n, rot);
        float2 p = (uv - 0.5) * texsize.xy / texsize.y;
        p = mul(p, rot);
        R = length(p);
        q.x = (log(R) * S - time) * 3.0;
        q.y = atan2(p.y, p.x);
        q += n * 0.3 + q1 + q.y;
        a += dot(cos(q + q2) / S, 1.0);
        n += sin(q);
        N += sin(q + q22) / S;
        S /= 0.99;
        j += 1.0;
    }

    float col = (.4 - a * 0.02) + 0.2 / length(N);
    float4 base = (col * sqrt(R)) * (2.0 + sin(float4(2,3,4,4) + a * 0.1));
    ret = base;
}

